#!/usr/bin/env node
// Prepares the Android project generated by `tauri android init` (src-tauri/gen/android):
//   1. copies the app's launcher icons (src-tauri/icons/android, made by `tauri icon`) over the
//      default Tauri icons that `android init` puts in app/src/main/res;
//   2. writes gen/android/keystore.properties (keyAlias, storePassword, keyPassword, storeFile);
//   3. patches gen/android/app/build.gradle.kts so the "release" build type is signed with it,
//      following the Tauri 2 guide on Android code signing.
// Idempotent: running it again only refreshes the icons and keystore.properties.
//
// Where the signing data comes from:
//   - CI: environment variables ANDROID_KEYSTORE_FILE (path of the decoded .jks),
//     ANDROID_KEYSTORE_PASSWORD, ANDROID_KEY_ALIAS and ANDROID_KEY_PASSWORD.
//   - Local machine: the folder ~/electronica-firma (or ELECTRONICA_FIRMA_DIR) with
//     electronica-release.jks and firma.properties (keyAlias, storePassword, keyPassword).
// Works the same on Windows, macOS and Linux.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const MARKER = 'electronica-firma';
const web = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const tauriDir = path.join(web, '..', 'src-tauri');
const androidDir = path.join(tauriDir, 'gen', 'android');
const iconsDir = path.join(tauriDir, 'icons', 'android');
const gradleFile = path.join(androidDir, 'app', 'build.gradle.kts');

function fail(message) {
  console.error(`android-preparar: ERROR: ${message}`);
  process.exit(1);
}

// Minimal java.util.Properties reader: key=value or key:value, comments with # or !.
function readProperties(file) {
  const result = {};
  for (const raw of fs.readFileSync(file, 'utf8').split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith('#') || line.startsWith('!')) continue;
    const m = /^([^=:\s]+)\s*[=:]\s*(.*)$/.exec(line);
    if (m) result[m[1]] = m[2].replace(/\\(.)/g, '$1');
  }
  return result;
}

// Escapes a value for a java.util.Properties file (backslashes, separators, non-ASCII).
function escapeProperty(value) {
  return value
    .replace(/\\/g, '\\\\')
    .replace(/([=:#!])/g, '\\$1')
    .replace(/^ /, '\\ ')
    .replace(/[^\x20-\x7e]/g, (c) => '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0'));
}

function signingFromEnv() {
  const env = process.env;
  if (!env.ANDROID_KEYSTORE_FILE) return null;
  const values = {
    storeFile: env.ANDROID_KEYSTORE_FILE,
    storePassword: env.ANDROID_KEYSTORE_PASSWORD ?? '',
    keyAlias: env.ANDROID_KEY_ALIAS ?? '',
    keyPassword: env.ANDROID_KEY_PASSWORD ?? '',
  };
  const names = {
    storePassword: 'ANDROID_KEYSTORE_PASSWORD',
    keyAlias: 'ANDROID_KEY_ALIAS',
    keyPassword: 'ANDROID_KEY_PASSWORD',
  };
  for (const [key, name] of Object.entries(names)) {
    if (!values[key]) fail(`la variable ${name} está vacía (¿falta el secreto en GitHub?).`);
  }
  return { source: 'variables de entorno', ...values };
}

function signingFromFolder() {
  const dir = process.env.ELECTRONICA_FIRMA_DIR || path.join(os.homedir(), 'electronica-firma');
  const jks = path.join(dir, 'electronica-release.jks');
  const props = path.join(dir, 'firma.properties');
  if (!fs.existsSync(jks)) fail(`no existe ${jks}`);
  if (!fs.existsSync(props)) fail(`no existe ${props}`);
  const p = readProperties(props);
  for (const key of ['keyAlias', 'storePassword', 'keyPassword']) {
    if (!p[key]) fail(`falta «${key}» en ${props}`);
  }
  return { source: dir, storeFile: jks, ...p };
}

if (!fs.existsSync(gradleFile)) {
  fail(`no existe ${gradleFile}. Ejecuta antes, desde web/: npm run tauri -- android init`);
}

// 1. Launcher icons.
if (!fs.existsSync(iconsDir)) fail(`no existe ${iconsDir}`);
fs.cpSync(iconsDir, path.join(androidDir, 'app', 'src', 'main', 'res'), { recursive: true, force: true });
console.log('android-preparar: iconos copiados desde src-tauri/icons/android.');

const signing = signingFromEnv() ?? signingFromFolder();
const storeFile = path.resolve(signing.storeFile);
if (!fs.existsSync(storeFile) || fs.statSync(storeFile).size === 0) {
  fail(`el almacén de claves ${storeFile} no existe o está vacío.`);
}

// 2. keystore.properties (forward slashes so the path also works on Windows).
const propsText =
  [
    '# Written by web/scripts/android-preparar.mjs. Never commit this file.',
    `keyAlias=${escapeProperty(signing.keyAlias)}`,
    `storePassword=${escapeProperty(signing.storePassword)}`,
    `keyPassword=${escapeProperty(signing.keyPassword)}`,
    `storeFile=${escapeProperty(storeFile.split(path.sep).join('/'))}`,
  ].join('\n') + '\n';
fs.writeFileSync(path.join(androidDir, 'keystore.properties'), propsText, { mode: 0o600 });

// Keep keystore.properties out of git even if gen/android is ever versioned.
const gitignore = path.join(androidDir, '.gitignore');
const ignored = fs.existsSync(gitignore) ? fs.readFileSync(gitignore, 'utf8') : '';
if (!/^\/?keystore\.properties\s*$/m.test(ignored)) {
  fs.appendFileSync(gitignore, (ignored && !ignored.endsWith('\n') ? '\n' : '') + 'keystore.properties\n');
}

// 3. build.gradle.kts
let gradle = fs.readFileSync(gradleFile, 'utf8');
const eol = gradle.includes('\r\n') ? '\r\n' : '\n';
if (gradle.includes(MARKER)) {
  console.log('android-preparar: build.gradle.kts ya tenía la firma configurada.');
} else {
  const buildTypes = [...gradle.matchAll(/^([ \t]*)buildTypes\s*\{/gm)];
  if (buildTypes.length !== 1) {
    fail(`se esperaba un único bloque «buildTypes {» en ${gradleFile} y hay ${buildTypes.length}.`);
  }
  const indent = buildTypes[0][1];
  const unit = indent || '    ';
  const i2 = indent + unit;
  const i3 = i2 + unit;
  const block = [
    `${indent}// ${MARKER}: release signing from keystore.properties (web/scripts/android-preparar.mjs)`,
    `${indent}signingConfigs {`,
    `${i2}create("release") {`,
    `${i3}val keystorePropertiesFile = rootProject.file("keystore.properties")`,
    `${i3}val keystoreProperties = Properties()`,
    `${i3}if (keystorePropertiesFile.exists()) {`,
    `${i3}${unit}FileInputStream(keystorePropertiesFile).use { stream -> keystoreProperties.load(stream) }`,
    `${i3}}`,
    `${i3}keyAlias = keystoreProperties.getProperty("keyAlias")`,
    `${i3}keyPassword = keystoreProperties.getProperty("keyPassword")`,
    `${i3}storePassword = keystoreProperties.getProperty("storePassword")`,
    `${i3}val storeFilePath: String? = keystoreProperties.getProperty("storeFile")`,
    `${i3}if (storeFilePath != null) {`,
    `${i3}${unit}storeFile = file(storeFilePath)`,
    `${i3}}`,
    `${i2}}`,
    `${indent}}`,
    '',
  ].join(eol);
  gradle = gradle.slice(0, buildTypes[0].index) + block + gradle.slice(buildTypes[0].index);

  // Inside `android { }` the name `java` resolves to the Android `java` extension, so fully qualified
  // `java.util.Properties` does not compile there: import the classes at the top of the script instead.
  const imports = ['import java.io.FileInputStream', 'import java.util.Properties']
    .filter((imp) => !new RegExp(`^${imp.replace(/\./g, '\\.')}\\s*$`, 'm').test(gradle));
  if (imports.length) gradle = imports.join(eol) + eol + gradle;

  const release = [...gradle.matchAll(/^([ \t]*)getByName\(\s*"release"\s*\)\s*\{[ \t]*\r?\n/gm)];
  if (release.length !== 1) {
    fail(`se esperaba un único «getByName("release") {» en ${gradleFile} y hay ${release.length}.`);
  }
  const at = release[0].index + release[0][0].length;
  const line = `${release[0][1]}${unit}signingConfig = signingConfigs.getByName("release") // ${MARKER}${eol}`;
  gradle = gradle.slice(0, at) + line + gradle.slice(at);

  fs.writeFileSync(gradleFile, gradle);
  console.log('android-preparar: build.gradle.kts preparado para firmar la versión release.');
}

// Final check: both pieces must be in place.
const check = fs.readFileSync(gradleFile, 'utf8');
if (!check.includes('signingConfigs {') || !check.includes('signingConfig = signingConfigs.getByName("release")')) {
  fail(`la configuración de firma no quedó en ${gradleFile}.`);
}
console.log(`android-preparar: firma tomada de ${signing.source}; alias «${signing.keyAlias}».`);
